// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(address actor) public {
        // actor must be admissible: not yet blacklisted, distribution still open
        vm.assume(actor != address(0));
        vm.assume(!c.blacklist(actor));
        vm.assume(!c.distributionFinished());

        uint256 distBefore = c.totalDistributed();
        uint256 balBefore = c.balanceOf(actor);

        vm.deal(actor, 1 wei);
        vm.prank(actor);
        c.getTokens{value: 1 wei}();

        uint256 balDelta = c.balanceOf(actor) - balBefore;
        uint256 distDelta = c.totalDistributed() - distBefore;

        // General rule: every token counted as distributed is also credited to
        // the recipient's balance (balance delta == totalDistributed delta).
        assertTrue(balDelta == distDelta, "distributed amount must be credited to recipient balance");
    }
}
